$('#root').innerHTML=`<div class="proto-bar"><span><span class="dot"></span>互動原型 <span class="desktop-only">／ 所有發送、排程與狀態均為模擬</span></span><div class="flex">${btn('guide','操作指南','','')}${btn('demo','體驗工具','','')}</div></div><div class="app ${ui.open?'chat-open':''}"><nav class="rail" aria-label="平台導覽"><div class="brand">獅</div><div class="rail-label">LION LEAD</div><button data-action="nav-hint">${icon('home')}首頁</button><button data-action="tour-info">${icon('calendar')}我帶的團</button><button class="active" data-action="list">${icon('chat')}訊息</button><div class="rail-foot">${avatar('陳','rose')}<small style="display:block;margin-top:8px;font-size:9px;text-align:center">導領・陳小姐</small></div></nav><aside class="sidebar" aria-label="聊天室清單，向下拉顯示搜尋"><div class="side-head"><div class="between"><h1>訊息</h1><div class="flex list-actions">${ib('qr','qr','團體加入 QR Code')}${ib('new','plus','新增對話')}</div></div><div class="search-reveal" ${ui.searchShown?'':'hidden'}><div class="search">${icon('search')}<input id="chat-search" placeholder="搜尋聊天室或旅客" value="${esc(ui.query)}" aria-label="搜尋聊天室"></div></div></div><div class="side-tabs">${['all','group','direct'].map((k,i)=>btn('tab', ['全部','公告／群組','私訊'][i],ui.tab===k?'active':'',`data-value="${k}"`)).join('')}</div><div class="chat-list">${chats.length?chats.map(x=>{const l=latest(x);return `<button data-action="open-chat" data-id="${x.id}" class="chat-item ${x.id===ui.chat?'active':''}">${chatAvatar(x)}<div class="grow"><div class="between"><span class="name">${esc(x.name)}${x.kind==='direct'?joinTag(person(x.members[0])):''}${x.kind==='internal'?'<span class="internal-badge">內部</span>':''}</span><time>${l?shortTime(l.at):'新對話'}</time></div><div class="snippet">${x.star?'置頂 · ':''}${esc(messageSummary(l)||'開始這段旅途的對話')}</div></div></button>`}).join(''):'<div class="empty">找不到符合的對話</div>'}</div></aside><main class="main"><header class="chat-head">${ib('list','back','返回聊天室列表').replace('class="iconbtn"','class="iconbtn mobile-back"')}<button class="chat-avatar" data-action="members" aria-label="${c.kind==='direct'?'查看旅客資訊':'查看成員清單'}">${chatAvatar(c).replace('<div','<span').replace('</div>','</span>')}</button><button class="chat-title" data-action="members" style="text-align:left;min-width:0"><h2>${esc(c.name)}${c.kind==='direct'?joinTag(person(c.members[0])):''}</h2></button><div class="head-actions">${['announcement','group'].includes(c.kind)?`<button class="member-summary" data-action="members" aria-label="查看成員，共${c.members.length}人"><span class="member-count">${c.members.length}</span>${icon('users')}</button>`:c.kind==='internal'?ib('members','users','成員與對話資訊'):''}</div></header>${state.offline?`<div class="offline-bar">${icon('wifi')}目前離線 · 可閱讀及編輯草稿，重新連線後才能發送</div>`:''}${c.kind==='direct'?travelerBrief(person(c.members[0])):''}<section class="messages" id="messages" aria-label="對話訊息">${state.messages.filter(m=>m.chat===c.id).map(renderMessage).join('')||`<div class="empty">${icon('chat')}<p>從一則訊息開始<br>一起照顧這趟旅程。</p></div>`}</section>${activeSchedules?`<div class="schedule-notice">${icon('clock')}本對話有 ${activeSchedules} 則待發送訊息 ${btn('schedules','查看排程','')}</div>`:''}<section class="compose" aria-label="編輯訊息">${d.confirm||d.attachments.length||d.reply||d.schedule?`<div class="draft-tags">${d.schedule?`<span class="draft-chip schedule-chip"><button data-action="schedule-new" class="flex" aria-label="修改草稿排程">${icon('clock')}排程 ${esc(d.schedule.localDate)} ${esc(d.schedule.localTime)} · ${d.schedule.zone==='Asia/Tokyo'?'日本':'台北'}</button>${ib('clear-schedule','close','取消草稿排程')}</span>`:''}${d.confirm?`<span class="draft-chip">${icon('check')}需確認收到 ${ib('toggle-confirm','close','取消要求確認')}</span>`:''}${d.reply?`<span class="draft-chip">回覆 ${esc(d.reply.name)}：${esc(d.reply.text.slice(0,18))} ${ib('clear-reply','close','取消引用')}</span>`:''}${d.attachments.map((a,i)=>`<span class="draft-chip">${a.kind==='itinerary'?btn('itinerary-edit-draft',icon('calendar')+esc(a.name),'draft-itinerary',`data-index="${i}"`):a.kind==='image'?`<img src="${esc(a.url)}" alt="待發圖片">${esc(a.name)}`:icon(a.kind==='location'?'pin':'file')+esc(a.name)}${ib('remove-attachment','close','移除附件',`data-index="${i}"`)}</span>`).join('')}</div>`:''}<div class="compose-row">${ib('plus','plus','開啟訊息工具')}<textarea id="draft-text" rows="1" placeholder="${c.kind==='announcement'?'寫一則給全團的公告…':'輸入訊息…'}" aria-label="訊息內容">${esc(d.text)}</textarea><div class="send-group"><button data-action="send" aria-label="${d.schedule?'排程發送':'立即發送'}" title="${d.schedule?'排程發送':'立即發送'}">${icon(d.schedule?'clock':'send')}</button></div></div>${ui.plus?`<div class="popover"><button data-action="toggle-confirm">${icon('check')}<div class="grow">要求確認收到<br><small>適用重要公告或集合提醒</small></div>${d.confirm?icon('check'):''}</button><button data-action="schedule-new">${icon('clock')}<div class="grow">排程訊息<br><small>${d.schedule?'修改此則訊息的發送時間':'選擇時間後繼續編輯訊息'}</small></div>${d.schedule?icon('check'):''}</button><hr><button data-action="upload">${icon('image')}照片／檔案附件</button><button data-action="location">${icon('pin')}地圖定位</button>${c.kind==='internal'?`<button data-action="traveler-module">${icon('user')}旅客模組</button>`:''}${c.kind!=='internal'?`<button data-action="itinerary-new">${icon('calendar')}每日行程概覽</button><button data-action="survey-new">${icon('file')}意見調查表</button><button data-action="templates">${icon('file')}模板</button>`:''}</div>`:''}<input type="file" id="upload-file" hidden multiple accept="image/*,.pdf,.doc,.docx,.xlsx,.txt"></section></main></div>`;
