function renderAttachment(a){if(a.kind==='survey')return renderSurveyCard(a);if(a.kind==='traveler')return renderTravelerCard(a);if(a.kind==='itinerary')return renderItineraryCard(a);if(a.kind==='image')return `<img class="msg-image" src="${esc(a.url)}" alt="${esc(a.name)}">`;if(a.kind==='location')return `<div class="map-card"><div class="map-art"><div class="map-pin"><span>●</span></div></div><div class="map-caption"><strong>${esc(a.name)}</strong><br>${esc(a.address||'集合定位')}<br><span class="muted">${esc(a.lat)}, ${esc(a.lng)}</span></div></div>`;return `<div class="file-card">${icon('file')}<div><strong>${esc(a.name)}</strong><br><small>${esc(a.size||'附件')} · 原型檔案紀錄</small></div></div>`;}
function renderMessage(m){
if(m.recalled)return `<article class="message recalled-message" data-message="${m.id}"><span>${m.sender==='me'?'你已收回訊息':'訊息已收回'}</span></article>`;
const own=m.sender==='me',p=person(m.sender),sent=m.status!=='failed',chat=state.chats.find(c=>c.id===m.chat);
const label=chat.kind==='direct'?(m.read.includes(chat.members[0])?'已讀':'未讀'):m.confirm?`已確認${m.confirmed.length}/未確認${chat.members.length-m.confirmed.length}`:`已讀${m.read.length}`;
const meta=own?`<button class="own-message-meta" data-action="${sent?'receipts':'retry'}" data-id="${m.id}" aria-label="${sent?label+'，查看訊息資訊':'發送失敗，點此重試'}"><span class="own-receipt ${sent?'':'failed'}">${sent?label:'發送失敗'}</span><time class="message-time">${shortTime(m.at)}</time></button>`:'';
return `<article class="message ${own?'own':''}" data-message="${m.id}">${!own?messageAvatar(m,p,false):''}<div class="msg-wrap">${!own?`<div class="msg-author">${messageAuthor(m,p,false)}${p?.role?'<span class="pill green">'+esc(p.role)+'</span>':''}</div>`:''}<div class="message-line">${meta}<div class="bubble" tabindex="0" aria-label="訊息，長按開啟操作">${m.forwarded?`<div class="forward">${icon('forward')}已轉發</div>`:''}${m.reply?`<div class="notice" style="margin-bottom:10px">回覆 ${esc(m.reply.name)}<br>${esc(m.reply.text.slice(0,80))}</div>`:''}${ui.translated.has(m.id)?`<div class="translated-original">${icon('translate')}<span>${nl(m.text)}</span></div>`:nl(m.text)}${m.attachments.map(renderAttachment).join('')}${renderMessageTranslation(m)}${m.confirm?`<div class="confirm-label">${icon('check')}此則訊息需確認收到</div>`:''}</div>${!own?`<time class="message-time">${shortTime(m.at)}</time>`:''}</div>${ui.translated.has(m.id)?btn('translation-language','翻譯設定','translation-settings-link',`data-id="${m.id}"`):''}</div></article>`;
}
