function openModal(type,data={}){ui.modal={type,...data};ui.modalQuery='';if(['new','forward'].includes(type)){ui.selected=new Set();ui.filter='all';ui.targetTab='people';}drawModal();}
function peopleList(people,mode='profile'){return people.map(p=>`<div class="person">${mode==='select'?`<label><input type="checkbox" data-select="${p.id}" ${ui.selected.has(p.id)?'checked':''}>`:''}${avatar(p.name.slice(-2))}<div class="grow"><div class="flex"><span class="name">${esc(p.name)}</span>${!p.joined?'<span class="pill amber">尚未加入</span>':''}</div><div class="sub">${esc(p.car)} · 房號 ${esc(p.room)} · ${esc(p.diet)}</div></div>${mode==='select'?'</label>':btn('profile','查看','btn small',`data-id="${p.id}"`)}</div>`).join('');}
function filterPeople(){return state.people.filter(p=>state.chats.find(c=>c.tour===state.tour&&c.kind==='announcement').members.includes(p.id)).filter(p=>!ui.modalQuery||p.name.includes(ui.modalQuery)).filter(p=>ui.filter==='all'||(ui.filter==='car1'?p.car==='1 車':ui.filter==='car2'?p.car==='2 車':ui.filter==='diet'?p.diet!=='一般餐':ui.filter==='pending'?!p.joined:ui.filter==='unread'?!getMsg('m1').read.includes(p.id):true));}
function pickerBody(){const opts=[['all','全部團員'],['car1','1 車'],['car2','2 車'],['diet','特殊餐食'],['pending','尚未加入'],['unread','未讀全團公告']];return `<div class="search">${icon('search')}<input id="person-search" placeholder="搜尋旅客姓名" value="${esc(ui.modalQuery)}" aria-label="搜尋旅客"></div><div class="filter-row"><select id="person-filter" aria-label="篩選團員">${opts.map(([v,l])=>`<option value="${v}" ${v===ui.filter?'selected':''}>${l}</option>`).join('')}</select>${btn('select-visible','全選目前名單','btn small')}</div><div class="selection-summary">已選 ${ui.selected.size} 位 · 尚未加入者仍會保留相關歷史訊息</div><div>${peopleList(filterPeople(),'select')||'<div class="empty">沒有符合的旅客</div>'}</div>`;}
const templateField=(id,label,type='text',required=true,placeholder='')=>({id,label,type,required,placeholder});
const messageTemplates=[
{id:'meeting',name:'集合提醒',icon:'users',description:'集合日期、時間與地點',fields:[templateField('date','集合日期','date'),templateField('time','集合時間','time'),templateField('place','集合地點','text',true,'例如：飯店 1 樓大廳'),templateField('note','補充說明','textarea',false,'例如：請提前 10 分鐘抵達')],compose:v=>`各位旅客您好：\n請於 ${v.date} ${v.time} 在「${v.place}」集合。${v.note?'\n\n'+v.note:''}\n謝謝大家配合！`},
{id:'hotel',name:'飯店入住',icon:'home',description:'飯店資訊與入住注意事項',fields:[templateField('hotel','飯店名稱','text',true,'請輸入飯店名稱'),templateField('date','入住日期','date'),templateField('time','入住時間','time',false),templateField('note','入住注意事項','textarea',false,'例如：早餐時間、房卡使用方式')],compose:v=>`各位旅客您好：\n${v.date} 將入住「${v.hotel}」。${v.time?'\n入住時間：'+v.time:''}${v.note?'\n\n'+v.note:''}\n祝大家入住愉快！`},
{id:'transport',name:'交通提醒',icon:'pin',description:'出發時間、交通方式與集合位置',fields:[templateField('transport','交通方式','text',true,'例如：遊覽車'),templateField('date','出發日期','date'),templateField('time','出發時間','time'),templateField('place','集合地點','text',true,'請輸入集合地點'),templateField('note','補充說明','textarea',false)],compose:v=>`各位旅客您好：\n我們將於 ${v.date} ${v.time} 搭乘${v.transport}出發。\n請至「${v.place}」集合。${v.note?'\n\n'+v.note:''}\n謝謝大家！`},
{id:'weather',name:'天氣提醒',icon:'calendar',description:'天氣概況與攜帶物品建議',fields:[templateField('date','提醒日期','date'),templateField('weather','天氣概況','text',true,'例如：氣溫偏低，午後可能有雨'),templateField('items','建議攜帶物品','text',false,'例如：薄外套、雨具'),templateField('note','補充說明','textarea',false)],compose:v=>`各位旅客您好：\n${v.date} 天氣提醒：${v.weather}。${v.items?'\n建議攜帶：'+v.items+'。':''}${v.note?'\n\n'+v.note:''}\n祝大家旅途愉快！`},
{id:'checkout',name:'退房提醒',icon:'clock',description:'退房時間與行李集合地點',fields:[templateField('date','退房日期','date'),templateField('time','退房時間','time'),templateField('place','行李集合地點','text',true,'例如：飯店 1 樓大廳'),templateField('note','補充說明','textarea',false,'例如：請確認隨身物品，並繳回房卡')],compose:v=>`各位旅客您好：\n請於 ${v.date} ${v.time} 前完成退房，並攜帶行李至「${v.place}」集合。${v.note?'\n\n'+v.note:''}\n謝謝大家配合！`}
];
function drawModal(){if(!ui.modal)return;const x=ui.modal,c=current();if(drawModuleModal(x,c))return;
if(x.type==='recall-confirm'){modal('收回訊息','<p class="recall-explanation">收回後，所有收件者將無法在對話中查看這則訊息。</p>',btn('close-modal','取消','btn')+btn('recall-confirm','收回訊息','btn primary',`data-id="${x.mid}"`));return;}
if(x.type==='templates'){
modal('選擇模板',`<div class="template-list">${messageTemplates.map(t=>`<button class="template-card" data-action="template-pick" data-id="${t.id}"><span class="avatar rose">${icon(t.icon)}</span><span class="grow"><strong>${esc(t.name)}</strong><small>${esc(t.description)}</small></span>${icon('chevron')}</button>`).join('')}</div>`,'','示範樣板 · '+c.name);return;
}
if(x.type==='template-fill'){
const t=messageTemplates.find(t=>t.id===x.templateId),values=x.values||{};
modal(t.name,`<div class="template-progress"><span>選擇模板</span><span class="active">02 填寫資料</span><span>預覽</span></div><div class="template-target">發送至：${esc(c.name)}</div><form id="template-form" class="stack">${t.fields.map(f=>`<label class="form-field"><span>${esc(f.label)}${f.required?' <span class="required">*</span>':' <span class="muted">（選填）</span>'}</span>${f.type==='textarea'?`<textarea id="template-field-${f.id}" rows="3" maxlength="600" placeholder="${esc(f.placeholder)}">${esc(values[f.id]||'')}</textarea>`:`<input id="template-field-${f.id}" type="${f.type}" value="${esc(values[f.id]||'')}" placeholder="${esc(f.placeholder)}" ${f.required?'required':''} maxlength="160">`}</label>`).join('')}</form>`,btn('templates','返回選擇','btn')+btn('template-preview','預覽訊息','btn primary'),'示範樣板 · 資料手動填寫');return;
}
if(x.type==='template-preview'){
const t=messageTemplates.find(t=>t.id===x.templateId);
modal('預覽訊息',`<div class="template-progress"><span>選擇模板</span><span>填寫資料</span><span class="active">03 預覽</span></div><div class="template-target">發送至：${esc(c.name)} · ${esc(t.name)}</div><div class="message-preview template-preview">${esc(t.compose(x.values))}</div>`,btn('template-edit','返回修改','btn')+btn('template-apply','帶回輸入框','btn primary'),'帶回後仍可編輯，尚未發送');return;
}
if(x.type==='members'&&c.kind==='internal'){
modal('內部對話資訊',`<div class="profile">${chatAvatar(c)}<div><h2>原Q信箱</h2><small>導領與公司內部溝通</small></div></div><div class="notice" style="margin-bottom:15px">此對話僅供導領與公司人員使用，旅客不可見。</div><div class="person">${avatar('陳','rose')}<div class="grow"><span class="name">陳小姐（我）</span><div class="sub">導領</div></div></div>${c.members.map(pid=>{const p=person(pid);return `<div class="person">${avatar(p.name.slice(-2),'sage')}<div class="grow"><span class="name">${esc(p.name)}</span><div class="sub">${esc(p.role)} · 公司內部</div></div></div>`;}).join('')}`,'',tours[state.tour].name);return;
}
if(x.type==='new'){modal('新增對話',`<div class="notice" style="margin-bottom:15px">選 1 位開啟私訊；選多位建立群組。可選取尚未加入的團員。</div>${pickerBody()}`,`<span class="grow">${ui.selected.size?'已選 '+ui.selected.size+' 位旅客':'請選擇旅客'}</span>${btn('new-next',ui.selected.size>1?'建立群組':'開啟私訊','btn primary',ui.selected.size?'':'disabled')}`,tours[state.tour].name);}
if(x.type==='group-create'){modal('建立群組',`<div class="stack"><label class="form-field">群組名稱<input id="group-name" maxlength="40" value="${esc([...ui.selected].slice(0,2).map(p=>person(p).name).join('、')+'等 '+ui.selected.size+' 人')}" aria-label="群組名稱"></label><div><span class="label">群組成員 · ${ui.selected.size} 位</span>${peopleList([...ui.selected].map(person),'select')}</div><div class="notice">群組成員會共用對話。若只需分別傳送既有訊息，可改用「轉發」。</div></div>`,btn('create-group','確認建立','btn primary'));}
if(x.type==='members'){modal(c.kind==='direct'?'旅客與對話資訊':'群組與成員',`<div class="profile">${chatAvatar(c)}<div class="grow"><h3>${esc(c.name)}</h3></div>${c.kind==='group'?ib('rename','edit','編輯群組名稱'):''}</div>${c.kind==='group'?`<div class="flex" style="margin-bottom:16px">${btn('favorite',icon('star')+(c.star?'已儲存常用群組':'儲存常用群組'),'btn small')}${btn('add-members',icon('plus')+'新增成員','btn small')}</div>`:''}<div class="table-stats"><div class="stat"><strong>${c.members.length}</strong><small>團員名單</small></div><div class="stat"><strong>${joinedCount(c)}</strong><small>已加入</small></div><div class="stat"><strong>${c.members.length-joinedCount(c)}</strong><small>尚未加入</small></div></div>${peopleList(c.members.map(person))}`, '', '加入狀態屬於旅客；閱讀與確認狀態屬於每則訊息。');}
if(x.type==='rename'){modal('編輯群組名稱',`<label class="form-field">名稱<input id="rename-name" maxlength="40" value="${esc(c.name)}"></label>`,btn('rename-save','儲存名稱','btn primary'));}
if(x.type==='add-members'){modal('新增群組成員',`${peopleList(state.people.filter(p=>!c.members.includes(p.id)),'select')||'<div class="empty">全團成員都已在群組內</div>'}`,btn('add-members-save','加入群組','btn primary'));}
if(x.type==='profile'){const p=person(x.pid);modal('旅客資訊',`<div class="profile">${avatar(p.name.slice(-2))}<div><h2>${esc(p.name)}</h2><small>${p.car} · 房號 ${p.room} · ${p.diet}</small></div></div>${!p.joined?'<span class="pill amber">尚未加入</span>':''}<div class="stack" style="margin-top:18px">${btn('private-person',icon('chat')+' 開啟個人對話','btn primary',`data-id="${p.id}"`)}${btn('guest-preview',icon('user')+' 旅客端預覽（模擬）','btn',`data-id="${p.id}"`)}</div>`, '', '示範資料，並非真實旅客資訊');}
if(x.type==='message-menu'){const m=getMsg(x.mid);modal('訊息操作',`<div class="message-preview" style="margin-bottom:16px">${esc(messageSummary(m))}</div><div class="demo-grid">${btn('reply',icon('chat')+' 回覆／引用','',`data-id="${m.id}"`)}${state.chats.find(c=>c.id===m.chat)?.kind==='internal'?'':btn('forward',icon('forward')+' 轉發訊息','',`data-id="${m.id}"`)}${btn('copy',icon('file')+' 複製文字','',`data-id="${m.id}"`)}${m.sender==='me'&&m.status!=='failed'?btn('receipts',icon('info')+' 訊息資訊與收件狀態','',`data-id="${m.id}"`):''}${m.sender!=='me'?btn('translate',icon('translate')+' 翻譯／收起翻譯','',`data-id="${m.id}"`):''}</div>`, '', '自己已發送的訊息可長按收回');}
if(x.type==='forward'){const m=getMsg(x.mid);modal('轉發訊息',`<div class="message-preview" style="margin-bottom:15px">${esc(messageSummary(m))}</div><div class="tabs">${btn('target-tab','旅客',ui.targetTab==='people'?'active':'', 'data-value="people"')}${btn('target-tab','公告／群組',ui.targetTab==='chats'?'active':'','data-value="chats"')}</div>${ui.targetTab==='people'?pickerBody():state.chats.filter(v=>v.tour===state.tour&&['announcement','group'].includes(v.kind)).map(v=>`<div class="person"><label><input type="checkbox" data-select="chat:${v.id}" ${ui.selected.has('chat:'+v.id)?'checked':''}>${chatAvatar(v)}<div><span class="name">${esc(v.name)}</span><div class="sub">${v.members.length} 位成員</div></div></label></div>`).join('')}`,`<span class="grow">已選 ${ui.selected.size} 個對象</span>${btn('forward-send','確認轉發','btn primary',ui.selected.size?'':'disabled')}`, '各旅客收到獨立訊息；選群組則發送至該群組。');}
if(x.type==='receipts'){const m=getMsg(x.mid),chat=state.chats.find(z=>z.id===m.chat);const tabs=[['unread','未讀 '+(chat.members.length-m.read.length)],['read','已讀 '+m.read.length],...(m.confirm?[['confirmed','已確認 '+m.confirmed.length],['unconfirmed','未確認 '+(chat.members.length-m.confirmed.length)]]:[])];let ps=chat.members.map(person).filter(p=>ui.detailTab==='read'?m.read.includes(p.id):ui.detailTab==='confirmed'?m.confirmed.includes(p.id):ui.detailTab==='unconfirmed'?!m.confirmed.includes(p.id):!m.read.includes(p.id));modal('訊息資訊',`<div class="message-preview">${esc(messageSummary(m))}</div><div class="between" style="margin:12px 0 16px"><small>發送時間 ${fullTime(m.at)}</small><span class="pill ${m.confirm?'red':''}">${m.confirm?'需確認收到':'一般訊息'}</span></div><div class="tabs">${tabs.map(([v,l])=>btn('receipt-tab',l,ui.detailTab===v?'active':'',`data-value="${v}"`)).join('')}</div>${ps.length?ps.map(p=>receiptPersonRow(p,m)).join(''):'<div class="empty">此狀態目前沒有旅客</div>'}`, '', '');}
if(x.type==='location'){modal('附上集合定位',`<div class="stack"><div class="map-card" style="width:100%"><div class="map-art" style="height:130px"><div class="map-pin"><span>●</span></div></div><div class="map-caption">示意地圖 · 不使用即時 GPS</div></div><label class="form-field">地點名稱<input id="location-name" value="京都車站中央口" maxlength="80"></label><label class="form-field">地址／集合說明<input id="location-address" value="中央口出站後，請在紅色團旗旁集合"></label><div class="form-grid"><label class="form-field">緯度<input id="location-lat" type="number" step="any" value="34.9858" min="-90" max="90"></label><label class="form-field">經度<input id="location-lng" type="number" step="any" value="135.7588" min="-180" max="180"></label></div></div>`,btn('location-add','加入草稿','btn primary'));}
if(x.type==='schedule'){
const scheduled=x.sid?state.schedules.find(z=>z.id===x.sid):null,d=scheduled||draft(),settings=scheduled||d.schedule||{};
const next=new Date(Date.now()+3600000);
const date=settings.localDate||`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`;
const time=settings.localTime||`${String(next.getHours()).padStart(2,'0')}:${String(next.getMinutes()).padStart(2,'0')}`;
modal(scheduled?'編輯排程':'設定排程訊息',`<div class="stack"><div class="notice">發送至：${esc((scheduled?state.chats.find(z=>z.id===scheduled.chat):c).name)}<br>${scheduled?'可修改尚未發送的內容與時間。':'設定時間後回到輸入框繼續編輯，最後按「排程發送」才會建立排程。'}</div>${scheduled?`<label class="form-field">訊息內容<textarea id="schedule-text" rows="4" aria-label="排程訊息內容">${esc(d.text)}</textarea></label>${d.attachments.map(renderAttachment).join('')}`:''}<div class="form-grid"><label class="form-field full">時區<select id="schedule-zone"><option value="Asia/Taipei" ${settings.zone==='Asia/Taipei'?'selected':''}>台北時間 · UTC+08:00</option><option value="Asia/Tokyo" ${settings.zone==='Asia/Tokyo'?'selected':''}>日本時間 · UTC+09:00</option></select></label><label class="form-field">發送日期<input type="date" id="schedule-date" value="${date}" required></label><label class="form-field">發送時間<input type="time" id="schedule-time" value="${time}" required></label></div>${scheduled?`<label class="flex" style="font-size:12px"><input id="schedule-confirm" type="checkbox" ${d.confirm?'checked':''}>要求旅客確認收到</label>`:''}<div class="small-note">原型中的排程會在此頁開啟時執行，也可透過體驗工具模擬到時發送。</div></div>`,btn('schedule-save',scheduled?'儲存變更':'套用至草稿','btn primary'));
}
if(x.type==='schedules'){const ss=state.schedules.filter(s=>state.chats.find(c=>c.id===s.chat)?.tour===state.tour).slice().sort((a,b)=>a.at.localeCompare(b.at));modal('排程訊息',`<div class="notice" style="margin-bottom:16px">${tours[state.tour].name}<br>顯示此團所有對話的排程。未發送前可修改或取消。</div>${ss.length?ss.map(s=>`<article class="schedule-card"><div class="between"><h3>${esc(state.chats.find(c=>c.id===s.chat).name)}</h3><span class="pill ${s.status==='pending'?'red':s.status==='sent'?'green':''}">${({pending:'待發送',sent:'已發送',cancelled:'已取消',failed:'發送失敗'})[s.status]}</span></div><p>${nl(messageSummary(s))}</p><small>${icon('clock')} ${esc(s.localDate)} ${esc(s.localTime)} · ${s.zone==='Asia/Tokyo'?'日本時間':'台北時間'}${s.confirm?' · 需確認收到':''}</small>${s.status==='pending'?`<div class="flex" style="margin-top:12px">${btn('schedule-edit','修改','btn small',`data-id="${s.id}"`)}${btn('schedule-cancel','取消排程','btn small danger',`data-id="${s.id}"`)}</div>`:''}</article>`).join(''):'<div class="empty">'+icon('clock')+'<p>目前沒有排程訊息<br>在對話輸入框左側「＋」選擇排程訊息。</p></div>'}`, '', '所有排程與發送均為本機模擬');}
if(x.type==='cancel-schedule'){modal('取消這則排程？',`<div class="notice">取消後不會發送。原型會保留「已取消」紀錄，與刪除已發訊息不同。</div>`,btn('schedules','返回','btn')+btn('schedule-cancel-confirm','確認取消','btn primary',`data-id="${x.sid}"`));}
if(x.type==='history'){const all=state.messages.filter(m=>m.sender==='me'&&state.chats.find(c=>c.id===m.chat)?.tour===state.tour).slice().reverse();const a=state.chats.find(c=>c.tour===state.tour&&c.kind==='announcement');modal('發送紀錄與未加入名單',`<div class="tabs">${btn('history-mode','發送紀錄',x.mode!=='pending'?'active':'','data-value="history"')}${btn('history-mode','尚未加入 '+(a.members.length-joinedCount(a)),x.mode==='pending'?'active':'','data-value="pending"')}</div>${x.mode==='pending'?peopleList(a.members.map(person).filter(p=>!p.joined)):all.map(m=>`<div class="history-item"><div class="between"><strong style="font-size:12px">${esc(state.chats.find(c=>c.id===m.chat).name)}</strong><span class="pill ${m.status==='failed'?'amber':'green'}">${m.status==='failed'?'發送失敗':'已發送'}</span></div><p>${nl(m.text||'[附件訊息]')}</p><small>${fullTime(m.at)} · ${m.forwarded?'轉發 · ':''}${m.confirm?'需確認收到':'一般訊息'}</small><div>${m.status==='failed'?btn('retry','重試','btn small',`data-id="${m.id}"`):btn('receipts','查看收件狀態','btn small',`data-id="${m.id}"`)}</div></div>`).join('')}`, '', '已發送代表平台已記錄，不代表所有旅客已收到或閱讀。');}
if(x.type==='guest'){const p=person(x.pid),related=state.messages.filter(m=>state.chats.find(c=>c.id===m.chat)?.members.includes(p.id)&&state.chats.find(c=>c.id===m.chat)?.tour===state.tour&&m.status!=='failed');modal('旅客端預覽 · '+p.name,`<div class="notice ${p.joined?'':'red'}" style="margin-bottom:15px">這是跨端流程的示範預覽，不是 S7 正式畫面。${p.joined?'查看後更新本機已讀回執。':'目前尚未加入；加入後可查看所有與自己相關的歷史訊息。'}</div>${!p.joined?btn('join-person','模擬完成加入','btn primary',`data-id="${p.id}" style="width:100%"`):`<div class="guest-messages">${related.map(m=>`<small style="display:block;margin:15px 0 6px">${esc(state.chats.find(c=>c.id===m.chat).name)} · ${fullTime(m.at)}</small><div class="bubble">${m.recalled?'<span class="recalled-text">訊息已收回</span>':`${ui.translated.has(m.id)?`<div class="translated-original">${icon('translate')}<span>${nl(m.text)}</span></div>`:nl(m.text)}${m.attachments.map(renderAttachment).join('')}`} ${!m.recalled&&m.confirm&&m.sender==='me'?btn('guest-confirm',m.confirmed.includes(p.id)?icon('check')+' 已確認收到':'確認收到',m.confirmed.includes(p.id)?'btn':'btn primary',`data-id="${m.id}" data-person="${p.id}" ${m.confirmed.includes(p.id)?'disabled':''}`):''}</div>`).join('')||'<div class="empty">目前沒有相關訊息</div>'}</div>`}`, '', '歷史可見範圍依收件對象，不受加入時間限制');}
if(x.type==='qr'){const cells=[];for(let y=0;y<21;y++)for(let z=0;z<21;z++){const finder=(ox,oy)=>z>=ox&&z<ox+7&&y>=oy&&y<oy+7&&((z===ox||z===ox+6||y===oy||y===oy+6)||(z>=ox+2&&z<=ox+4&&y>=oy+2&&y<=oy+4));if(finder(0,0)||finder(14,0)||finder(0,14)||((z>7&&y>7)&&((z*13+y*7)%5<2)))cells.push(`<rect x="${z}" y="${y}" width="1" height="1" fill="#343e37"/>`);}modal('邀請旅客加入',`<div class="qr-wrap"><h3>${esc(tours[state.tour].name)}</h3><svg class="qr" viewBox="-1 -1 23 23" aria-label="示意 QR Code，不可掃描">${cells.join('')}</svg><span class="pill amber">示意 QR Code · 不可掃描</span><p class="small-note" style="margin-top:12px">正式串接時由 S7 提供加入與身分核對流程。<br>此處可選取尚未加入的旅客，模擬完成核對。</p></div>${peopleList(state.people.filter(p=>!p.joined))}`, '', '僅供原型流程展示');}
if(x.type==='language'){modal('語言設定',`<div class="stack"><label class="form-field">想閱讀的語言<select id="translation-language"><option ${ui.lang==='繁體中文'?'selected':''}>繁體中文</option><option ${ui.lang==='English'?'selected':''}>English</option></select></label></div>`,btn('language-save','儲存','btn primary'));}
if(x.type==='guest-picker'){modal('選擇旅客預覽',state.people.map(p=>`<div class="person">${avatar(p.name.slice(-2))}<div class="grow">${esc(p.name)} ${!p.joined?'<span class="pill amber">尚未加入</span>':''}</div>${btn('guest-preview','預覽','btn small',`data-id="${p.id}"`)}</div>`).join(''));}
if(x.type==='demo'){modal('體驗工具',`<div class="notice" style="margin-bottom:16px">以下操作只影響此瀏覽器的示範資料，不會向真實旅客發送訊息。</div><div class="demo-grid">${btn('guest-picker',icon('user')+'<div>旅客端預覽<small>模擬加入、閱讀歷史訊息與確認收到</small></div>','')}${btn('simulate-reply',icon('chat')+'<div>模擬對方回覆<small>在目前私訊、群組或內部對話增加回覆</small></div>','')}${btn('run-schedules',icon('clock')+'<div>模擬排程到時<small>立即執行此團所有待發訊息</small></div>','')}${btn('toggle-offline',icon('wifi')+`<div>${state.offline?'恢復連線':'模擬離線'}<small>驗證草稿保留與發送限制</small></div>`,'')}${btn('fail-next',icon('refresh')+`<div>${state.failNext?'已啟用：下次發送失敗':'模擬下次發送失敗'}<small>驗證失敗訊息與重試</small></div>`,'')}${btn('reset-ask',icon('refresh')+'<div>重設示範資料<small>清除本機變更，恢復初始情境</small></div>','')}</div>`);}
if(x.type==='guide'){modal('原型操作指南',`<div class="stack"><div class="notice">以導領對客溝通為範圍。模板先使用示範樣板，欄位手動填寫；自動帶入與正式串接尚未提供。</div><ol class="tips-list"><li>在列表頂端向下拉，可開啟搜尋；右上角 QR Code 可邀請旅客加入整團。</li><li>「原Q信箱」是導領與公司內部的對話，可按「＋」選擇旅客模組，選擇並預覽後，直接發送特定旅客的資料卡討論。</li><li>在「全團公告」寫訊息，按「＋」啟用要求確認。</li><li>按左側「＋」選擇模板，填寫並預覽後帶回輸入框。</li><li>選擇「每日行程概覽」，選取公司備妥的日期，預覽後發送。</li><li>點私訊頭像查看旅客資料；儲存個人備註後會同步顯示在私訊上方，僅導遊自己可見。</li><li>按左側「＋」選擇排程訊息，設定時間後回到草稿，最後按排程發送。</li><li>長按訊息可複製、回覆、轉發，或查看訊息資訊。</li><li>開啟成員資訊，查看「尚未加入」旅客。</li><li>透過旅客端預覽模擬加入、閱讀及確認。</li><li>從體驗工具測試回覆、離線與發送失敗。</li></ol><div class="small-note">資料保存在此瀏覽器。所有姓名、狀態、定位及 QR Code 均為示範，不是正式收送服務。</div></div>`,btn('close-modal','開始體驗','btn primary'));}
if(x.type==='reset'){modal('重設原型？','<div class="notice">將清除新增對話、訊息、附件、排程與模擬狀態，恢復初始示範資料。</div>',btn('close-modal','保留','btn')+btn('reset-confirm','重設','btn primary'));}
if(x.type==='tour-info'){modal('團體資訊',`<div class="stack"><div class="eyebrow">${tours[state.tour].code}</div><h2>${esc(tours[state.tour].name)}</h2><p>${tours[state.tour].date} · ${tours[state.tour].destination}</p><div class="notice">此原型以團體區分對話與收件人。既有團務功能與提醒中心不在本次範圍；原Q信箱為公司內部對話示範。</div></div>`);}
}
function openChat(cid){ui.chat=cid;ui.open=true;ui.plus=false;ui.sendMenu=false;closeModal();render();}
function directFor(pid){let c=state.chats.find(c=>c.tour===state.tour&&c.kind==='direct'&&c.members[0]===pid);if(!c){c={id:id(),tour:state.tour,kind:'direct',name:person(pid).name,members:[pid]};state.chats.push(c);save();}return c;}
function makeMessage(chat,data){const m={id:id(),chat,sender:'me',text:data.text||'',confirm:!!data.confirm,attachments:JSON.parse(JSON.stringify(data.attachments||[])),reply:data.reply||null,read:[],confirmed:[],at:new Date().toISOString(),status:state.failNext?'failed':'sent',forwarded:!!data.forwarded};state.failNext=false;state.messages.push(m);save();return m;}
function validDraft(d){if(current().kind!=='internal'&&d.attachments.some(a=>a.kind==='traveler')){toast('旅客模組僅供公司內部討論。');return false;}if(!d.text.trim()&&!d.attachments.length){toast('先輸入訊息或加入附件。');return false;}if(state.offline){toast('目前離線，草稿已保留，連線後再發送。');return false;}return true;}
function markRead(pid){const now=new Date().toISOString();state.messages.filter(m=>m.sender==='me'&&!m.recalled&&m.status==='sent'&&state.chats.find(c=>c.id===m.chat)?.tour===state.tour&&state.chats.find(c=>c.id===m.chat)?.members.includes(pid)).forEach(m=>{if(!m.read.includes(pid))m.read.push(pid);m.readAt=m.readAt||{};m.readAt[pid]=m.readAt[pid]||now;});save();}
function executeSchedule(s){const m=makeMessage(s.chat,s);s.status=m.status==='failed'?'failed':'sent';s.message=m.id;save();}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el){if(event.target.classList.contains('overlay-backdrop'))closeModal();return;}if(el.disabled)return;const a=el.dataset.action,pid=el.dataset.id,v=el.dataset.value;if(el.closest('#message-actions'))closeMessageActions();
if(['copy','reply','translate','forward','receipts','retry','translation-language'].includes(a)&&getMsg(pid)?.recalled){toast('此訊息已收回');return;}
if(handleModuleAction(a,el))return;
switch(a){
case 'close-modal':closeModal();break;
case 'list':ui.open=false;ui.searchShown=false;ui.query='';ui.plus=false;ui.sendMenu=false;render();break;
case 'open-chat':openChat(pid);break;
case 'tab':ui.tab=v;render();break;
case 'plus':ui.plus=!ui.plus;ui.sendMenu=false;render();break;
case 'send-menu':ui.sendMenu=!ui.sendMenu;ui.plus=false;render();break;
case 'toggle-confirm':draft().confirm=!draft().confirm;ui.plus=false;save();render();$('#draft-text').focus();break;
case 'clear-reply':draft().reply=null;save();render();break;
case 'remove-attachment':draft().attachments.splice(Number(el.dataset.index),1);save();render();break;
case 'upload':ui.plus=false;$('#upload-file').click();break;
case 'send':{
const d=draft();if(!validDraft(d))return;
if(d.schedule){
if(new Date(d.schedule.at).getTime()<=Date.now()){toast('排程時間已過，請點草稿上的排程時間重新設定。');return;}
state.schedules.push({id:id(),chat:ui.chat,...JSON.parse(JSON.stringify(d)),...d.schedule,status:'pending'});
state.drafts[ui.chat]={text:'',confirm:false,attachments:[]};ui.plus=false;save();render();toast('已加入排程（模擬）');break;
}
const m=makeMessage(ui.chat,d);state.drafts[ui.chat]={text:'',confirm:false,attachments:[]};ui.plus=false;ui.sendMenu=false;save();render();toast(m.status==='failed'?'示範發送失敗，可點訊息下方重試。':'訊息已發送（模擬）');break;
}
case 'retry':if(state.offline){toast('請先恢復連線。');break;}getMsg(pid).status='sent';save();closeModal();render();toast('重試成功（模擬）');break;
case 'new':openModal('new');break;
case 'select-visible':filterPeople().forEach(p=>ui.selected.add(p.id));drawModal();break;
case 'new-next':if(ui.selected.size===1){openChat(directFor([...ui.selected][0]).id);}else if(ui.selected.size>1){ui.modal={type:'group-create'};drawModal();}break;
case 'create-group':{const name=$('#group-name').value.trim();if(!name||ui.selected.size<2){toast('請填寫名稱，並至少選擇 2 位旅客。');return;}const c={id:id(),tour:state.tour,kind:'group',name,members:[...ui.selected]};state.chats.push(c);save();openChat(c.id);toast('群組已建立');break;}
case 'members':if(current().kind==='direct')openModal('profile',{pid:current().members[0]});else openModal('members');break;
case 'rename':openModal('rename');break;
case 'rename-save':{const name=$('#rename-name').value.trim();if(!name){toast('請輸入群組名稱。');return;}current().name=name;save();render();openModal('members');toast('已更新名稱');break;}
case 'favorite':current().star=!current().star;save();render();drawModal();toast(current().star?'已儲存為常用群組':'已取消常用群組');break;
case 'add-members':ui.selected=new Set();openModal('add-members');break;
case 'add-members-save':if(!ui.selected.size){toast('請選擇要加入的成員。');return;}current().members=[...new Set([...current().members,...ui.selected])];save();render();openModal('members');toast('已更新群組成員');break;
case 'profile':openModal('profile',{pid});break;
case 'private-person':openChat(directFor(pid).id);break;
case 'message-menu':showMessageActions(pid);break;
case 'forward':openModal('forward',{mid:pid});break;
case 'target-tab':ui.targetTab=v;drawModal();break;
case 'forward-send':{if(state.offline){toast('目前離線，請恢復連線後轉發。');return;}const original=getMsg(ui.modal.mid);const targets=new Set([...ui.selected].map(t=>t.startsWith('chat:')?t.slice(5):directFor(t).id));if(!targets.size)return;for(const target of targets)makeMessage(target,{...original,reply:null,forwarded:true});closeModal();render();toast(`已轉發至 ${targets.size} 個對話（模擬）`);break;}
case 'reply':{const m=getMsg(pid);draft().reply={name:m.sender==='me'?'陳小姐':person(m.sender)?.name||'旅客',text:messagePlainText(m)};save();closeModal();render();$('#draft-text').focus();break;}
case 'copy':{const m=getMsg(pid);try{await navigator.clipboard.writeText(messagePlainText(m));toast('已複製文字');}catch{toast('此瀏覽器不允許複製，可選取訊息文字。');}closeModal();break;}
case 'translate':{const box=$('#messages'),top=box.scrollTop;if(ui.translated.has(pid))ui.translated.delete(pid);else ui.translated.add(pid);closeModal();render();$('#messages').scrollTop=top;break;}
case 'receipts':ui.detailTab=getMsg(pid).confirm?'unconfirmed':'unread';openModal('receipts',{mid:pid});break;
case 'receipt-tab':ui.detailTab=v;drawModal();break;
case 'location':ui.plus=false;render();openModal('location');break;
case 'templates':ui.plus=false;render();openModal('templates');break;
case 'template-pick':openModal('template-fill',{templateId:pid,values:{}});break;
case 'template-preview':{
const t=messageTemplates.find(t=>t.id===ui.modal.templateId),values={};
for(const f of t.fields){const input=$('#template-field-'+f.id);if((f.required&&!input.value.trim())||!input.checkValidity()){input.reportValidity();input.focus();if(!input.value.trim())toast('請填寫'+f.label);return;}values[f.id]=input.value.trim();}
ui.modal={type:'template-preview',templateId:t.id,values};drawModal();break;
}
case 'template-edit':ui.modal.type='template-fill';drawModal();break;
case 'template-apply':{
const t=messageTemplates.find(t=>t.id===ui.modal.templateId),text=t.compose(ui.modal.values),d=draft();
d.text=d.text.trim()?d.text.replace(/\s+$/,'')+'\n\n'+text:text;save();closeModal();render();const input=$('#draft-text');input.style.height='auto';input.style.height=Math.min(input.scrollHeight,110)+'px';input.focus();toast('模板已帶回草稿，確認後再發送');break;
}
case 'location-add':{const name=$('#location-name').value.trim(),lat=Number($('#location-lat').value),lng=Number($('#location-lng').value);if(!name||!Number.isFinite(lat)||!Number.isFinite(lng)||lat< -90||lat>90||lng< -180||lng>180){toast('請填寫地點名稱及有效座標。');return;}draft().attachments.push({kind:'location',name,address:$('#location-address').value.trim(),lat,lng});save();closeModal();render();break;}
case 'schedule-new':ui.plus=false;ui.sendMenu=false;render();openModal('schedule');break;
case 'clear-schedule':delete draft().schedule;save();render();toast('已改為一般訊息，內容已保留');break;
case 'schedule-save':{
const x=ui.modal,scheduled=x.sid?state.schedules.find(s=>s.id===x.sid):null;
const date=$('#schedule-date').value,time=$('#schedule-time').value,zone=$('#schedule-zone').value;
if(!date||!time){toast('請選擇日期與時間。');return;}
const parsed=new Date(`${date}T${time}:00${zone==='Asia/Tokyo'?'+09:00':'+08:00'}`);
if(!Number.isFinite(parsed.getTime())||parsed.getTime()<=Date.now()){toast('請選擇未來的發送時間，並確認時區。');return;}
const timing={localDate:date,localTime:time,zone,at:parsed.toISOString()};
if(scheduled){
const text=$('#schedule-text').value.trim();if(!text&&!scheduled.attachments.length){toast('請輸入訊息或加入附件。');return;}
if(state.offline){toast('目前離線，請先恢復連線。');return;}
Object.assign(scheduled,timing,{text,confirm:$('#schedule-confirm').checked});save();render();openModal('schedules');toast('排程已更新');
}else{draft().schedule=timing;save();closeModal();render();toast('排程時間已套用，編輯後按「排程發送」');}
break;
}
case 'schedules':openModal('schedules');break;
case 'schedule-edit':openModal('schedule',{sid:pid});break;
case 'schedule-cancel':openModal('cancel-schedule',{sid:pid});break;
case 'schedule-cancel-confirm':state.schedules.find(s=>s.id===pid).status='cancelled';save();render();openModal('schedules');toast('已取消排程');break;
case 'history':openModal('history');break;
case 'history-mode':ui.modal.mode=v;drawModal();break;
case 'guest-preview':if(person(pid).joined)markRead(pid);render();openModal('guest',{pid});break;
case 'join-person':person(pid).joined=true;markRead(pid);render();openModal('guest',{pid});toast('已模擬加入，相關歷史訊息已顯示');break;
case 'guest-confirm':{const p=el.dataset.person,m=getMsg(pid);if(!m.confirmed.includes(p))m.confirmed.push(p);if(!m.read.includes(p))m.read.push(p);m.confirmedAt=m.confirmedAt||{};m.confirmedAt[p]=new Date().toISOString();save();render();drawModal();toast('已確認收到（模擬）');break;}
case 'qr':openModal('qr');break;
case 'language':openModal('language');break;
case 'translation-language':closeMessageActions();ui.lang=translationTarget(getMsg(pid));openModal('language');break;
case 'language-save':{const top=$('#messages').scrollTop;ui.lang=$('#translation-language').value;state.translationLanguage=ui.lang;save();closeModal();render();$('#messages').scrollTop=top;toast('已更新閱讀語言');break;}
case 'guest-picker':openModal('guest-picker');break;
case 'demo':openModal('demo');break;
case 'guide':openModal('guide');break;
case 'simulate-reply':{const c=current();if(c.kind==='announcement'){toast('公告不開放旅客回覆，請先切到私訊或群組。');return;}const p=c.members.map(person).find(p=>p.joined);if(!p){toast('目前尚無已加入的成員。');return;}state.messages.push({id:id(),chat:c.id,sender:p.id,text:c.kind==='internal'?'收到，我們會協助確認安排，有更新再通知您。':'收到，謝謝領隊！想再確認一下，明天是 08:00 在大廳集合對嗎？',translation:'Thank you! Just to confirm, are we meeting in the lobby at 8:00 tomorrow?',at:new Date().toISOString(),read:[],confirmed:[],attachments:[],status:'sent'});save();closeModal();render();toast('已新增旅客回覆（模擬）');break;}
case 'run-schedules':{if(state.offline){toast('請先恢復連線。');return;}const ss=state.schedules.filter(s=>s.status==='pending'&&state.chats.find(c=>c.id===s.chat)?.tour===state.tour);ss.forEach(executeSchedule);save();render();openModal('schedules');toast(ss.length?`已模擬執行 ${ss.length} 則排程`:'目前沒有待發送排程');break;}
case 'toggle-offline':state.offline=!state.offline;save();closeModal();render();toast(state.offline?'已模擬離線，草稿會保留':'已恢復連線');break;
case 'fail-next':state.failNext=!state.failNext;save();drawModal();toast(state.failNext?'下次發送將模擬失敗':'已取消失敗模擬');break;
case 'reset-ask':openModal('reset');break;
case 'reset-confirm':state=initial();ensureInternal(state);enrichTravelers(state);upgradeCompactTraveler(state);ensureTalkGroup(state);ui.chat='a1';ui.searchShown=false;ui.tab='all';ui.query='';ui.translated=new Set();save();closeModal();render();toast('已重設示範資料');break;
case 'tour-info':openModal('tour-info');break;
case 'nav-hint':toast('此原型聚焦 IM；既有首頁不在本次範圍。');break;
}
});
let listPull=null;
function revealSearch(){if(ui.searchShown)return;ui.searchShown=true;render();}
document.addEventListener('touchstart',e=>{const sidebar=e.target.closest('.sidebar');if(!sidebar||ui.modal||ui.searchShown||e.target.closest('input,textarea,select'))return;listPull={y:e.touches[0].clientY,x:e.touches[0].clientX,atTop:sidebar.querySelector('.chat-list').scrollTop<=0};},{passive:true});
document.addEventListener('touchmove',e=>{if(!listPull||!listPull.atTop||!e.touches.length)return;const dy=e.touches[0].clientY-listPull.y,dx=e.touches[0].clientX-listPull.x;if(dy>18&&Math.abs(dy)>Math.abs(dx)){e.preventDefault();if(dy>=55){listPull=null;revealSearch();}}},{passive:false});
document.addEventListener('touchend',()=>{listPull=null;},{passive:true});
document.addEventListener('touchcancel',()=>{listPull=null;},{passive:true});
document.addEventListener('wheel',e=>{const sidebar=e.target.closest('.sidebar');if(!sidebar||ui.searchShown||ui.modal)return;if(e.deltaY< -30&&sidebar.querySelector('.chat-list').scrollTop<=0){e.preventDefault();revealSearch();}},{passive:false});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.target.closest('input,textarea,select')&&!ui.modal){e.preventDefault();ui.open=false;revealSearch();$('#chat-search')?.focus();}});
document.addEventListener('input',e=>{if(e.target.id==='draft-text'){draft().text=e.target.value;e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,110)+'px';save();}if(e.target.id==='chat-search'){const start=e.target.selectionStart;ui.query=e.target.value;render();$('#chat-search').focus();$('#chat-search').setSelectionRange(start,start);}if(e.target.id==='person-search'){const start=e.target.selectionStart;ui.modalQuery=e.target.value;drawModal();const inp=$('#person-search');inp.focus();inp.setSelectionRange(start,start);}});
document.addEventListener('change',async e=>{if(e.target.dataset.select){if(e.target.checked)ui.selected.add(e.target.dataset.select);else ui.selected.delete(e.target.dataset.select);drawModal();}if(e.target.id==='person-filter'){ui.filter=e.target.value;drawModal();}if(e.target.id==='tour-select'){state.tour=e.target.value;ui.chat=state.chats.find(c=>c.tour===state.tour&&c.kind==='announcement').id;ui.query='';ui.tab='all';save();render();}if(e.target.id==='upload-file'){const files=[...e.target.files];for(const f of files){if(f.size>3*1024*1024){toast('原型附件限制每個 3 MB。');continue;}if(f.type.startsWith('image/')){const url=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(f);});draft().attachments.push({kind:'image',name:f.name,url});}else{draft().attachments.push({kind:'file',name:f.name,size:Math.max(1,Math.round(f.size/1024))+' KB'});}}save();render();toast('附件已加入草稿');}});
document.addEventListener('submit',e=>{if(e.target.id==='template-form'){e.preventDefault();document.querySelector('[data-action="template-preview"]')?.click();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();if(ui.plus||ui.sendMenu){ui.plus=false;ui.sendMenu=false;render();}}if(e.target.id==='draft-text'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();document.querySelector('[data-action="send"]').click();}});
setInterval(()=>{if(state.offline)return;const due=state.schedules.filter(s=>s.status==='pending'&&new Date(s.at).getTime()<=Date.now());if(due.length){due.forEach(executeSchedule);render();if(ui.modal?.type==='schedules')drawModal();toast('排程訊息已模擬發送');}},5000);
setupMessageGestures();
render();
